@push('scripts')<script src="https://cdn.tiny.cloud/1/no-api-key/tinymce/7/tinymce.min.js" referrerpolicy="origin"></script><script>document.addEventListener('DOMContentLoaded',()=>{tinymce.init({selector:'#blog-editor',height:550,plugins:'lists link image table autoresize',toolbar:'undo redo | blocks | bold italic underline | alignleft aligncenter alignright | bullist numlist | blockquote | link image table',menubar:false,branding:false});document.getElementById('add-category').addEventListener('click',async()=>{const name=prompt('Category name');if(!name)return;const r=await fetch('{{ route('admin.blog.categories.quick') }}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}','Accept':'application/json'},body:JSON.stringify({name})});if(!r.ok){alert('Unable to create category.');return;}const c=await r.json(),s=document.getElementById('category_id');s.add(new Option(c.name,c.id,true,true));});});</script>@endpush
